package com.bank.strength;

import com.bank.strength.model.StrengthClaim;
import com.bank.strength.service.StrengthVerifier;
import java.util.logging.*;

// Runnable demo: verify a "biggest strength" answer like a bank verifies a transaction.
public class StrengthDemo {
    private static final Logger log = Logger.getLogger("Strength");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        StrengthVerifier verifier = new StrengthVerifier(log);

        // Vague claim — strength named, no evidence.
        StrengthClaim vague = new StrengthClaim(
            "Debugging", null, null, 0, 0);
        verifier.verify(vague);

        // Strong claim — full STAR with a measurable result.
        StrengthClaim strong = new StrengthClaim(
            "Root-cause analysis under production pressure",
            "A payment outage during peak hours froze all transfers for Rajesh and Priya.",
            "I read the logs and thread dumps, found a database deadlock, "
              + "fixed the lock ordering, and added a monitor so it cannot recur.",
            120,   // MTTR before, minutes
            30);   // MTTR after, minutes
        verifier.verify(strong);
    }
}
