package com.bank.strength.model;

// Models a strength claim like a bank transaction: it needs evidence to be accepted.
public class StrengthClaim {
    private final String strength;
    private final String situation;   // the specific context
    private final String action;      // what you personally did
    private final int resultBefore;   // measurable before
    private final int resultAfter;    // measurable after

    public StrengthClaim(String strength, String situation, String action,
                         int resultBefore, int resultAfter) {
        this.strength = strength;
        this.situation = situation;
        this.action = action;
        this.resultBefore = resultBefore;
        this.resultAfter = resultAfter;
    }

    public String getStrength() { return strength; }
    public String getSituation() { return situation; }
    public String getAction() { return action; }
    public int getResultBefore() { return resultBefore; }
    public int getResultAfter() { return resultAfter; }

    // A verifiable claim has a situation, an action, and a measurable change.
    public boolean hasEvidence() {
        return situation != null && action != null && resultBefore != resultAfter;
    }
}
