package com.bank.strength.service;

import com.bank.strength.model.StrengthClaim;
import java.util.logging.*;

// Accepts a strength claim only if it carries a full STAR story with a result.
public class StrengthVerifier {
    private final Logger log;

    public StrengthVerifier(Logger log) { this.log = log; }

    public void verify(StrengthClaim claim) {
        if (!claim.hasEvidence()) {
            log.warning(() -> "UNVERIFIED strength \"" + claim.getStrength()
                + "\" — attach a situation, action, and measurable result.");
            return;
        }
        int improvement = claim.getResultBefore() - claim.getResultAfter();
        log.info(() -> "VERIFIED strength: " + claim.getStrength());
        log.info(() -> "   Situation: " + claim.getSituation());
        log.info(() -> "   Action: " + claim.getAction());
        log.info(() -> "   Result: improved by " + improvement
            + " (from " + claim.getResultBefore() + " to " + claim.getResultAfter() + ")");
    }
}
